V111_B64 = """"""

def embedded_source(blob: str) -> str:
    return zlib.decompress(base64.b64decode(blob)).decode("utf-8")

V111_SOURCE = embedded_source(V111_B64)

ROOT = Path(".")
LAB = ROOT / "mfp3_confluence_lab"
LAB.mkdir(exist_ok=True)

YEARLY_CSV = LAB / "confluence_yearly.csv"
PATTERNS_CSV = LAB / "confluence_patterns.csv"
PORTFOLIO_CSV = LAB / "confluence_portfolio.csv"
METRICS_CSV = LAB / "confluence_metrics.csv"
CURRENT_CSV = LAB / "current_confluence_signals.csv"
STATE_JSON = LAB / "confluence_state.json"

TARGETS = ["QQQ", "ECH", "CPER"]
HORIZONS = [1, 5, 20]
FIRST_TEST_YEAR = 2018

MAX_FEATURES = 12
MAX_PATTERNS_DISCOVERY = 24
MAX_PATTERNS_FINAL = 10
MIN_SUPPORT_DISCOVERY = 35
MIN_SUPPORT_VALIDATION = 12

Z_ON = 0.35
ONE_WAY_COST = 0.0015
MAX_ASSET_WEIGHT = 0.30
INITIAL_CAPITAL = 10_000_000.0
RUN_EVERY_DAYS = 14
TASK_NAME = "MFP3_ONEFILE_V112_DAILY"

FLOORS = [0.0, 0.25, 0.50, 0.67]

# ---------------------------------------------------------------------
# v1.11 runtime
# ---------------------------------------------------------------------

def get_v111_namespace():
    g = {
        "__name__": "mfp3_v111_library",
        "__file__": "<embedded:v1.11>",
        "__builtins__": __builtins__,
    }
    exec(compile(V111_SOURCE, g["__file__"], "exec"), g, g)
    return g

def run_v111(args):
    old = sys.argv[:]
    try:
        sys.argv = ["mfp3_v111_embedded.py"]
        if args.full:
            sys.argv.append("--full")

        g = {
            "__name__": "mfp3_v111_embedded",
            "__file__": "<embedded:v1.11>",
            "__builtins__": __builtins__,
        }
        exec(compile(V111_SOURCE, g["__file__"], "exec"), g, g)
        g["main"]()
    finally:
        sys.argv = old

# ---------------------------------------------------------------------
# Task scheduler
# ---------------------------------------------------------------------

def install_this_file():
    if os.name != "nt":
        raise SystemExit("--install sólo funciona en Windows.")

    script = str(Path(__file__).resolve())
    python = str(Path(sys.executable).resolve())
    action = f'"{python}" "{script}"'

    p = subprocess.run(
        [
            "schtasks", "/Create",
            "/TN", TASK_NAME,
            "/TR", action,
            "/SC", "DAILY",
            "/ST", "18:30",
            "/F",
        ],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )

    if p.returncode != 0:
        print(p.stdout)
        print(p.stderr)
        raise SystemExit("No se pudo instalar la tarea.")

    print(p.stdout.strip())
    print("Instalado: v1.12 se ejecutará diariamente a las 18:30.")

def uninstall_this_file():
    if os.name != "nt":
        raise SystemExit("--uninstall sólo funciona en Windows.")

    p = subprocess.run(
        ["schtasks", "/Delete", "/TN", TASK_NAME, "/F"],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    print((p.stdout or p.stderr).strip())

# ---------------------------------------------------------------------
# Core utilities
# ---------------------------------------------------------------------

def now_utc():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")

def perf(ret):
    r = pd.Series(ret).fillna(0.0)
    if len(r) == 0:
        return {
            "total_return": 0.0,
            "sharpe": 0.0,
            "max_drawdown": 0.0,
            "ann_vol": 0.0,
        }

    curve = (1 + r).cumprod()
    vol = float(r.std() * np.sqrt(252))
    sharpe = float(r.mean() * 252 / vol) if vol > 1e-12 else 0.0
    dd = curve / curve.cummax() - 1

    return {
        "total_return": float(curve.iloc[-1] - 1),
        "sharpe": sharpe,
        "max_drawdown": float(dd.min()),
        "ann_vol": vol,
    }

def weeklyize(pos):
    p = pos.fillna(0.0).clip(0, 1)
    out = pd.Series(index=p.index, dtype=float)
    state = 0.0

    for i, (dt, v) in enumerate(p.items()):
        if i == 0 or i % 5 == 0:
            state = float(v)
        out.loc[dt] = state

    return out

def strategy_returns(position, daily_ret):
    target = weeklyize(position)
    exec_pos = target.shift(1).fillna(0.0)
    held = target.shift(2).fillna(0.0)
    turnover = exec_pos.diff().abs().fillna(exec_pos.abs())
    gross = held * daily_ret.fillna(0.0)
    net = gross - turnover * ONE_WAY_COST
    return net, held, turnover

def utility(ret, turnover):
    p = perf(ret)
    return (
        p["sharpe"]
        + 0.30 * p["total_return"]
        - 0.60 * abs(p["max_drawdown"])
        - 0.012 * float(turnover.sum())
    ), p

# ---------------------------------------------------------------------
# Temporal data
# ---------------------------------------------------------------------

def year_slice(df, years):
    return df[df.index.year.isin(years)].copy()

def enough_year(df, year):
    return int(np.sum(df.index.year == year)) >= 100

def feature_cols(df):
    exclude = {"price_clp", "daily_ret_clp"}
    for h in HORIZONS:
        exclude |= {f"fwd_ret_{h}", f"y_up_{h}"}
    return [c for c in df.columns if c not in exclude]

# ---------------------------------------------------------------------
# Stable feature discovery
# ---------------------------------------------------------------------

def discover_features(df, h, years):
    feats = feature_cols(df)
    rows = []

    for f in feats:
        fold_ics = []

        for y in years:
            z = df[df.index.year == y][[f, f"fwd_ret_{h}"]].dropna()
            if len(z) < 80:
                continue

            ic = z[f].rank().corr(z[f"fwd_ret_{h}"].rank())
            if pd.notna(ic):
                fold_ics.append(float(ic))

        if len(fold_ics) < max(2, len(years) - 1):
            continue

        mean_ic = float(np.mean(fold_ics))
        direction = 1.0 if mean_ic >= 0 else -1.0
        consistency = float(
            np.mean([
                np.sign(x) == np.sign(mean_ic)
                for x in fold_ics if x != 0
            ])
        ) if any(x != 0 for x in fold_ics) else 0.0

        # Penaliza señales muy variables entre años.
        stability = abs(mean_ic) * consistency / (
            1.0 + float(np.std(fold_ics))
        )

        rows.append({
            "feature": f,
            "mean_ic": mean_ic,
            "direction": direction,
            "consistency": consistency,
            "stability": stability,
            "folds": len(fold_ics),
        })

    st = pd.DataFrame(rows)
    if st.empty:
        return pd.DataFrame()

    # Mínimo de consistencia; si quedan pocos, elige los más estables.
    good = st[
        (st["consistency"] >= 0.60)
        & (st["mean_ic"].abs() >= 0.01)
    ].copy()

    if len(good) < 6:
        good = st.sort_values(
            ["stability", "consistency"],
            ascending=False,
        ).head(MAX_FEATURES)
    else:
        good = good.sort_values(
            ["stability", "consistency"],
            ascending=False,
        ).head(MAX_FEATURES)

    return good

# ---------------------------------------------------------------------
# Directional states
# ---------------------------------------------------------------------

def scaling_from_discovery(discovery, features):
    stats = {}

    for f in features:
        s = pd.to_numeric(discovery[f], errors="coerce")
        med = float(s.median())
        mad = float((s - med).abs().median())

        # Robust z scale.
        scale = 1.4826 * mad
        if not np.isfinite(scale) or scale < 1e-8:
            scale = float(s.std())

        if not np.isfinite(scale) or scale < 1e-8:
            scale = 1.0

        stats[f] = (med, scale)

    return stats

def directional_matrix(z, feature_table, scaling):
    out = pd.DataFrame(index=z.index)

    for r in feature_table.itertuples():
        f = r.feature
        med, scale = scaling[f]
        raw = (
            pd.to_numeric(z[f], errors="coerce") - med
        ) / scale

        out[f] = raw * float(r.direction)

    return out

# ---------------------------------------------------------------------
# Pattern search: singles, pairs, triples
# ---------------------------------------------------------------------

def candidate_patterns(features):
    fs = list(features)

    pats = []
    for f in fs:
        pats.append((f,))

    for pair in itertools.combinations(fs, 2):
        pats.append(pair)

    # triples only among top 8 to limit combinatorial explosion
    for tri in itertools.combinations(fs[:8], 3):
        pats.append(tri)

    return pats

def active_mask(state_df, pattern):
    m = pd.Series(True, index=state_df.index)
    for f in pattern:
        m &= state_df[f] > Z_ON
    return m

def discovery_pattern_table(
    discovery,
    states,
    feature_table,
    h,
):
    target = pd.to_numeric(
        discovery[f"fwd_ret_{h}"],
        errors="coerce",
    )
    valid_target = target.dropna()
    base_mean = float(valid_target.mean()) if len(valid_target) else 0.0
    base_hit = float((valid_target > 0).mean()) if len(valid_target) else 0.5

    rows = []

    features = feature_table["feature"].tolist()

    for pat in candidate_patterns(features):
        m = active_mask(states, pat) & target.notna()
        n = int(m.sum())

        if n < MIN_SUPPORT_DISCOVERY:
            continue

        r = target[m]
        mean = float(r.mean())
        hit = float((r > 0).mean())
        edge = mean - base_mean
        hit_edge = hit - base_hit
        sd = float(r.std())

        if not np.isfinite(sd) or sd <= 1e-10:
            t_like = 0.0
        else:
            t_like = edge / (sd / np.sqrt(n))

        # Multiple-testing guardrail:
        # exige ventaja positiva y premia soporte/repetición.
        score = (
            max(0.0, t_like)
            * (n / (n + 100.0))
            * max(0.0, 0.50 + hit_edge)
        )

        if edge <= 0 or hit_edge <= -0.02:
            continue

        rows.append({
            "pattern": " & ".join(pat),
            "members_json": json.dumps(pat),
            "size": len(pat),
            "support_discovery": n,
            "base_mean": base_mean,
            "active_mean": mean,
            "edge_discovery": edge,
            "base_hit": base_hit,
            "active_hit": hit,
            "t_like": t_like,
            "discovery_score": score,
        })

    tab = pd.DataFrame(rows)
    if tab.empty:
        return tab

    # Diversity: evita elegir 20 variantes casi iguales.
    tab = tab.sort_values(
        ["discovery_score", "support_discovery"],
        ascending=False,
    )

    selected = []
    member_sets = []

    for r in tab.itertuples(index=False):
        members = set(json.loads(r.members_json))

        too_similar = False
        for prev in member_sets:
            overlap = len(members & prev) / max(1, len(members | prev))
            if overlap >= 0.80:
                too_similar = True
                break

        if too_similar:
            continue

        selected.append(r._asdict())
        member_sets.append(members)

        if len(selected) >= MAX_PATTERNS_DISCOVERY:
            break

    return pd.DataFrame(selected)

# ---------------------------------------------------------------------
# Validation weighting
# ---------------------------------------------------------------------

def validate_patterns(
    validation,
    states,
    pattern_table,
    h,
):
    if pattern_table.empty:
        return pd.DataFrame()

    target = pd.to_numeric(
        validation[f"fwd_ret_{h}"],
        errors="coerce",
    )
    base = target.dropna()
    base_mean = float(base.mean()) if len(base) else 0.0
    base_hit = float((base > 0).mean()) if len(base) else 0.5

    rows = []

    for r in pattern_table.itertuples(index=False):
        pat = tuple(json.loads(r.members_json))
        m = active_mask(states, pat) & target.notna()
        n = int(m.sum())

        if n < MIN_SUPPORT_VALIDATION:
            continue

        rr = target[m]
        mean = float(rr.mean())
        hit = float((rr > 0).mean())
        edge = mean - base_mean
        hit_edge = hit - base_hit

        # Empirical shrinkage toward zero.
        shrink = n / (n + 30.0)
        shrunk_edge = edge * shrink

        # Must survive separate validation year.
        if shrunk_edge <= 0 or hit_edge < -0.03:
            continue

        weight_raw = (
            shrunk_edge
            * np.sqrt(n)
            * (1.0 + max(-0.2, hit_edge))
        )

        rows.append({
            **r._asdict(),
            "support_validation": n,
            "edge_validation": edge,
            "hit_validation": hit,
            "hit_edge_validation": hit_edge,
            "shrunk_edge_validation": shrunk_edge,
            "weight_raw": weight_raw,
        })

    vt = pd.DataFrame(rows)
    if vt.empty:
        return vt

    vt = vt.sort_values(
        ["weight_raw", "support_validation"],
        ascending=False,
    ).head(MAX_PATTERNS_FINAL).copy()

    total = vt["weight_raw"].clip(lower=0).sum()

    if total <= 0:
        return pd.DataFrame()

    vt["weight"] = (
        vt["weight_raw"].clip(lower=0) / total
    )

    return vt

# ---------------------------------------------------------------------
# Pattern score and floor selection
# ---------------------------------------------------------------------

def weighted_pattern_score(states, validated):
    score = pd.Series(0.0, index=states.index)

    if validated.empty:
        return score

    total_w = float(validated["weight"].sum())
    if total_w <= 0:
        return score

    for r in validated.itertuples(index=False):
        pat = tuple(json.loads(r.members_json))
        active = active_mask(states, pat).astype(float)
        score += float(r.weight) * active

    return (score / total_w).clip(0, 1)

def choose_floor(validation, score):
    rows = []

    for floor in FLOORS:
        position = floor + (1.0 - floor) * score
        net, held, turnover = strategy_returns(
            position,
            validation["daily_ret_clp"],
        )
        u, p = utility(net, turnover)

        rows.append({
            "floor": floor,
            "utility": u,
            "return": p["total_return"],
            "sharpe": p["sharpe"],
            "drawdown": p["max_drawdown"],
            "turnover": float(turnover.sum()),
        })

    table = pd.DataFrame(rows).sort_values(
        ["utility", "return"],
        ascending=False,
    )

    return float(table.iloc[0]["floor"]), table

# ---------------------------------------------------------------------
# One horizon / one future year
# ---------------------------------------------------------------------

def evaluate_horizon(df, test_year, h):
    discovery_years = [
        test_year - 4,
        test_year - 3,
        test_year - 2,
    ]
    val_year = test_year - 1

    if not all(enough_year(df, y) for y in discovery_years + [val_year, test_year]):
        return None

    discovery = year_slice(df, discovery_years)
    validation = year_slice(df, [val_year])
    test = year_slice(df, [test_year])

    feature_table = discover_features(
        df, h, discovery_years
    )

    if len(feature_table) < 4:
        return None

    features = feature_table["feature"].tolist()
    scaling = scaling_from_discovery(
        discovery, features
    )

    disc_states = directional_matrix(
        discovery, feature_table, scaling
    )
    val_states = directional_matrix(
        validation, feature_table, scaling
    )
    test_states = directional_matrix(
        test, feature_table, scaling
    )

    patterns = discovery_pattern_table(
        discovery,
        disc_states,
        feature_table,
        h,
    )

    validated = validate_patterns(
        validation,
        val_states,
        patterns,
        h,
    )

    if validated.empty:
        # No evidence; only floor 0 in this Challenger.
        val_score = pd.Series(0.0, index=validation.index)
        floor = 0.0
        floor_table = pd.DataFrame()
    else:
        val_score = weighted_pattern_score(
            val_states, validated
        )
        floor, floor_table = choose_floor(
            validation, val_score
        )

    val_position = floor + (1.0 - floor) * val_score
    val_net, _, val_turn = strategy_returns(
        val_position,
        validation["daily_ret_clp"],
    )
    val_u, val_p = utility(val_net, val_turn)

    test_score = weighted_pattern_score(
        test_states, validated
    )
    test_position = floor + (1.0 - floor) * test_score
    test_net, held, test_turn = strategy_returns(
        test_position,
        test["daily_ret_clp"],
    )
    test_u, test_p = utility(test_net, test_turn)

    return {
        "horizon": h,
        "feature_table": feature_table,
        "patterns_discovery": patterns,
        "patterns_validated": validated,
        "floor": floor,
        "floor_table": floor_table,
        "validation_utility": val_u,
        "validation_perf": val_p,
        "test_utility": test_u,
        "test_perf": test_p,
        "test_score": test_score,
        "test_position": held,
        "test_turnover": test_turn,
        "test_ret": test_net,
        "test_frame": test,
    }

# ---------------------------------------------------------------------
# Walk-forward per asset
# ---------------------------------------------------------------------

def run_asset(asset, df):
    yearly = []
    pattern_rows = []
    daily_rows = []

    latest = int(df.index.max().year)

    for year in range(FIRST_TEST_YEAR, latest + 1):
        candidates = []

        for h in HORIZONS:
            res = evaluate_horizon(
                df, year, h
            )
            if res is not None:
                candidates.append(res)

        if not candidates:
            continue

        # Horizon frozen using validation only.
        best = max(
            candidates,
            key=lambda x: x["validation_utility"],
        )

        p = best["test_perf"]

        yearly.append({
            "asset": asset,
            "test_year": year,
            "horizon": best["horizon"],
            "floor": best["floor"],
            "validation_utility": best["validation_utility"],
            "validation_return": best["validation_perf"]["total_return"],
            "validation_sharpe": best["validation_perf"]["sharpe"],
            "future_return": p["total_return"],
            "future_sharpe": p["sharpe"],
            "future_drawdown": p["max_drawdown"],
            "future_turnover": float(best["test_turnover"].sum()),
            "mean_position": float(best["test_position"].mean()),
            "n_features": len(best["feature_table"]),
            "n_patterns": len(best["patterns_validated"]),
        })

        for r in best["patterns_validated"].itertuples(index=False):
            pattern_rows.append({
                "asset": asset,
                "test_year": year,
                "horizon": best["horizon"],
                "floor": best["floor"],
                "pattern": r.pattern,
                "size": r.size,
                "support_discovery": r.support_discovery,
                "edge_discovery": r.edge_discovery,
                "support_validation": r.support_validation,
                "edge_validation": r.edge_validation,
                "hit_validation": r.hit_validation,
                "weight": r.weight,
            })

        z = pd.DataFrame(index=best["test_frame"].index)
        z["asset"] = asset
        z["year"] = year
        z["horizon"] = best["horizon"]
        z["floor"] = best["floor"]
        z["confluence_score"] = best["test_score"]
        z["position"] = best["test_position"]
        z["turnover"] = best["test_turnover"]
        z["strategy_ret"] = best["test_ret"]
        z["daily_ret_clp"] = best["test_frame"]["daily_ret_clp"]
        daily_rows.append(z)

        print(
            f"  {asset} {year}: H={best['horizon']} | "
            f"floor={best['floor']:.2f} | "
            f"patterns={len(best['patterns_validated'])} | "
            f"futuro={p['total_return']:+.2%} | "
            f"Sharpe={p['sharpe']:.2f}"
        )

    return (
        pd.DataFrame(yearly),
        pd.DataFrame(pattern_rows),
        pd.concat(daily_rows).sort_index()
        if daily_rows else pd.DataFrame(),
    )

# ---------------------------------------------------------------------
# Portfolio
# ---------------------------------------------------------------------

def build_portfolio(daily, frames):
    idx = pd.DatetimeIndex(
        sorted(daily.index.unique())
    )

    strat = pd.Series(0.0, index=idx)
    bench = pd.Series(0.0, index=idx)

    for asset in TARGETS:
        z = daily[daily["asset"] == asset]

        sr = (
            z["strategy_ret"]
            .groupby(z.index).last()
            .reindex(idx).fillna(0.0)
        )
        strat += MAX_ASSET_WEIGHT * sr

        bench += (
            MAX_ASSET_WEIGHT
            * frames[asset]["daily_ret_clp"]
            .reindex(idx).fillna(0.0)
        )

    out = pd.DataFrame(index=idx)
    out["strategy_ret"] = strat
    out["benchmark_ret"] = bench
    out["capital_strategy"] = (
        INITIAL_CAPITAL * (1 + strat).cumprod()
    )
    out["capital_benchmark"] = (
        INITIAL_CAPITAL * (1 + bench).cumprod()
    )

    return out

def metrics(port):
    s = perf(port["strategy_ret"])
    b = perf(port["benchmark_ret"])

    return pd.DataFrame([
        {"name": "CONFLUENCE_CHALLENGER", **s},
        {"name": "BENCHMARK_30_30_30_CLP", **b},
    ])

# ---------------------------------------------------------------------
# Current summary
# ---------------------------------------------------------------------

def current_summary(yearly, patterns):
    if yearly.empty:
        return pd.DataFrame()

    latest = int(yearly["test_year"].max())
    rows = []

    for asset in TARGETS:
        y = yearly[
            (yearly["asset"] == asset)
            & (yearly["test_year"] == latest)
        ]

        if y.empty:
            continue

        r = y.iloc[-1]

        p = patterns[
            (patterns["asset"] == asset)
            & (patterns["test_year"] == latest)
            & (patterns["horizon"] == r["horizon"])
        ].sort_values("weight", ascending=False)

        rows.append({
            "asset": asset,
            "research_year": latest,
            "horizon": int(r["horizon"]),
            "floor": float(r["floor"]),
            "validation_utility": float(r["validation_utility"]),
            "historical_future_return": float(r["future_return"]),
            "historical_future_sharpe": float(r["future_sharpe"]),
            "top_confluences": " | ".join(
                f"{x.pattern} [{x.weight:.2f}]"
                for x in p.head(6).itertuples()
            ),
        })

    return pd.DataFrame(rows)

# ---------------------------------------------------------------------
# Cadence
# ---------------------------------------------------------------------

def confluence_due(force=False):
    if force or not STATE_JSON.exists():
        return True

    try:
        state = json.loads(
            STATE_JSON.read_text(encoding="utf-8")
        )
        last = pd.Timestamp(state["last_completed_utc"])
        now = pd.Timestamp.now(tz="UTC")

        if last.tzinfo is None:
            last = last.tz_localize("UTC")
        else:
            last = last.tz_convert("UTC")

        return (now - last).days >= RUN_EVERY_DAYS

    except Exception:
        return True

def save_state():
    STATE_JSON.write_text(
        json.dumps(
            {
                "last_completed_utc": now_utc(),
                "version": "v1.12",
            },
            indent=2,
        ),
        encoding="utf-8",
    )

# ---------------------------------------------------------------------
# Lab
# ---------------------------------------------------------------------

def run_confluence_lab():
    ns = get_v111_namespace()

    print("\n[Confluence] Descargando y construyendo historia...")
    market = ns["download_history"]()

    frames = {
        asset: ns["build_frame"](asset, market)
        for asset in TARGETS
    }

    ys = []
    ps = []
    ds = []

    print("\n[Confluence] Walk-forward nested...")

    for asset in TARGETS:
        y, p, d = run_asset(
            asset, frames[asset]
        )

        if len(y):
            ys.append(y)
        if len(p):
            ps.append(p)
        if len(d):
            ds.append(d)

    yearly = pd.concat(ys, ignore_index=True)
    patterns = (
        pd.concat(ps, ignore_index=True)
        if ps else pd.DataFrame()
    )
    daily = pd.concat(ds).sort_index()

    port = build_portfolio(
        daily, frames
    )
    met = metrics(port)
    cur = current_summary(
        yearly, patterns
    )

    yearly.to_csv(
        YEARLY_CSV,
        index=False,
        encoding="utf-8-sig",
    )
    patterns.to_csv(
        PATTERNS_CSV,
        index=False,
        encoding="utf-8-sig",
    )
    port.to_csv(
        PORTFOLIO_CSV,
        encoding="utf-8-sig",
    )
    met.to_csv(
        METRICS_CSV,
        index=False,
        encoding="utf-8-sig",
    )
    cur.to_csv(
        CURRENT_CSV,
        index=False,
        encoding="utf-8-sig",
    )

    save_state()

    print("\n" + "=" * 92)
    print("CONFLUENCE DISCOVERY — RESULTADO")
    print("=" * 92)

    with pd.option_context(
        "display.max_columns", None,
        "display.width", 190,
    ):
        print(met)

    print(
        "\nCapital Confluence Challenger:",
        f"${port['capital_strategy'].iloc[-1]:,.0f} CLP"
    )
    print(
        "Capital Benchmark:",
        f"${port['capital_benchmark'].iloc[-1]:,.0f} CLP"
    )

    print("\nCoincidencias históricas actuales:")
    with pd.option_context(
        "display.max_columns", None,
        "display.width", 220,
    ):
        print(cur)

# ---------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------

def main():
    p = argparse.ArgumentParser()
    p.add_argument("--confluence", action="store_true")
    p.add_argument("--install", action="store_true")
    p.add_argument("--uninstall", action="store_true")
    p.add_argument("--status", action="store_true")
    p.add_argument("--full", action="store_true")
    args = p.parse_args()

    if args.install:
        install_this_file()
        return

    if args.uninstall:
        uninstall_this_file()
        return

    if args.status:
        print("\nMFP-3 v1.12 STATUS")
        print("Confluence Lab:", LAB.resolve())
        print("Confluence due:", confluence_due(False))
        print("Metrics:", METRICS_CSV.exists())
        print("Patterns:", PATTERNS_CSV.exists())
        return

    print("\n" + "=" * 94)
    print("MFP-3 ONE FILE v1.12 — CONFLUENCE DISCOVERY ENGINE")
    print("=" * 94)

    # Todo el sistema anterior sigue funcionando.
    run_v111(args)

    if confluence_due(args.confluence):
        print(
            "\n[v1.12] Buscando coincidencias históricas de señales. "
            "Este laboratorio puede tardar varios minutos..."
        )
        run_confluence_lab()
    else:
        print(
            "\n[v1.12] Confluence Lab ya está actualizado. "
            "Se repite automáticamente cada 14 días."
        )

    print(
        "\nEl motor de coincidencias sigue siendo Challenger. "
        "No modifica v1.7-FROZEN."
    )

if __name__ == "__main__":
    main()
